"""Actual EE client callers and generated bytes on one fake shared transport.

No Node, device, RPC or EXTERNAL backend is started by these regressions.
They require the real matching generated schema package at validation time.
"""
import dataclasses
import importlib.util
from pathlib import Path
import threading
import unittest
from unittest.mock import patch

import flatbuffers

from fake_transport import FakeTransport
from test_controller import ControllerHarness, make_command
from test_end_effector_codec import info_object, state_object, touch_object, pack, target, decode
from locomotion_aorta import (
    CONTROL_REQUEST_TOPIC, CONTROL_STATUS_TOPIC, ControllerClosedError,
    ExternalController, ExternalPhase, InvalidCommandError, NotRunningError,
    PullController, PullStateSource,
)
